e-box textarea{width:100%;min-height:220px;max-height:55vh;resize:vertical;overflow:auto;line-height:1.5}.section{border-top:1px solid var(--line);margin-top:18px;padding-top:12px}.section h3{margin:0 0 8px;font-size:17px}.link-list{margin:0;padding-left:20px}.link-list li{margin:5px 0}.link-list a{color:#174a8b}.picker{display:flex;gap:7px;flex-wrap:wrap;margin-top:9px}.picker input,.picker select{min-width:220px;max-width:100%}.photo-grid{display:flex;flex-wrap:wrap;gap:10px}.photo-grid a{display:block}.photo-grid img{width:145px;height:110px;object-fit:cover;border:1px solid var(--line);border-radius:6px}.action-table{width:100%;border-collapse:collapse}.action-table th,.action-table td{border-bottom:1px solid var(--line);padding:7px;text-align:left;vertical-align:top}.action-table input{width:100%}.message{margin-bottom:12px;color:#24683b;font-weight:700}@media(max-width:900px){main{grid-template-columns:1fr}.detail-head{flex-wrap:wrap}.audit{margin-left:auto}}@media(max-width:650px){.top{flex-wrap:wrap;padding:10px}.statusbox{width:100%}.userbar{justify-content:flex-start}.brand h1{font-size:20px}.grid{grid-template-columns:1fr}.audit{width:100%;grid-template-columns:auto 1fr}.adminlink,.logout{font-size:0!important;width:30px;justify-content:center;padding:0}.adminlink::first-letter,.logout::first-letter{font-size:16px}main{padding:8px}}
