<header class="top"><img class="logo" src="logo.png" alt="VvE Beheer logo"><div class="brand"><h1><?=tenantNameHtml()?></h1><small>Uw VvE · Database</small></div><div class="statusbox"><strong>Verbonden</strong><span id="stats">Projecten laden…</span><div class="userbar"><span class="rolebadge">👤 <?=htmlspecialchars((string)$user['name'],ENT_QUOTES,'UTF-8')?> · <?=htmlspecialchars((string)$user['role'],ENT_QUOTES,'UTF-8')?></span><span class="versionbadge">GUI V8.60</span><?php renderInstructionMenu();?><a class="adminlink" href="assistant.php">✨ Assistent</a><a class="adminlink" href="documents.php">📁 Bestanden</a><?php if($admin):?><a class="adminlink" href="settings.php">⚙ Instellingen</a><?php endif;?><form action="./" method="post" style="display:inline"><input type="hidden" name="action" value="logout"><input type="hidden" name="csrf" value="<?=htmlspecialchars(csrfToken(),ENT_QUOTES,'UTF-8')?>"><button class="logout" type="submit">↪ Uitloggen</button></form></div></div></header>
