<main><section class="panel"><div class="panel-head"><div class="headrow"><h2>Projecten</h2><?php if($admin):?><button class="btn primary" onclick="newProject()">＋ Nieuw record</button><?php endif;?></div><div class="filters"><label for="status">Status</label><select id="status" onchange="loadList()"><option value="all">Alle</option><option value="groen">🟢 Groen</option><option value="oranje">🟠 Oranje</option><option value="rood">🔴 Rood</option></select><label for="sort">Sorteren</label><select id="sort" onchange="renderList()"><option value="az">A–Z (naam)</option><option value="za">Z–A (naam)</option><option value="recent">Laatst gewijzigd</option></select></div></div><div class="sidebar-search"><input id="search" placeholder="Zoek projectnaam of tekst…" oninput="debouncedList()"></div><div id="list"></div></section><section class="panel"><div class="detail-head"><div><h2 id="title">Selecteer een project</h2><div id="subtitle" class="detail-sub"></div></div><div class="audit" id="audit" hidden></div></div><div class="detail-body" id="detail"><div class="notice">Selecteer links een project of maak een nieuw project aan.</div></div></section></main>
<script>
const CAN_EDIT=<?=json_encode($admin)?>,CSRF=<?=json_encode(csrfToken())?>;let rows=[],current=null,phase='Haalbaarheid',listTimer=null,assets=[],docs=[],stabuOptions=[],mjopOptions=[],projectStatusOptions=[];const $=id=>document.getElementById(id),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;','\"':'&quot;',"'":'&#39;'}[c]));
async function req(action,opts={}){const id=opts.id??current?.project?.ProjectID??0;const url='project_api.php?action='+encodeURIComponent(action)+'&id='+encodeURIComponent(id)+(opts.query?'&'+opts.query:'');const init={method:opts.method||'GET',headers:{'X-CSRF-Token':CSRF},credentials:'same-origin',cache:'no-store'};if(opts.body instanceof FormData)init.body=opts.body;else if(opts.body!==undefined){init.method='POST';init.headers['Content-Type']='application/json';init.body=JSON.stringify(opts.body)}const r=await fetch(url,init),d=await r.json();if(!r.ok||!d.ok)throw Error(d.error||'Verzoek mislukt');return d}
function err(e){alert(e.message||String(e))}function projectStatusLabel(code){return ({groen:'🟢 Groen — op schema',oranje:'🟠 Oranje — aandacht nodig',rood:'🔴 Rood — geblokkeerd'})[code]||code}function renderProjectStatusFilters(){const filter=$('status'),current=filter.value||'all';filter.innerHTML='<option value="all">Alle</option>'+projectStatusOptions.map(x=>'<option value="'+esc(x.id)+'">'+esc(x.label)+'</option>').join('');filter.value=projectStatusOptions.some(x=>String(x.id)===current)?current:'all'}function debouncedList(){clearTimeout(listTimer);listTimer=setTimeout(loadList,250)}
async function loadList(){try{const d=await req('list',{query:'q='+encodeURIComponent($('search').value)+'&status='+encodeURIComponent($('status').value)});rows=d.rows;$('stats').textContent=rows.length+' resultaten · '+d.total+' projecten';renderList()}catch(e){$('list').innerHTML='<div class="error">'+esc(e.message)+'</div>'}}
function renderList(){const sorted=[...rows];const mode=$('sort').value;sorted.sort((a,b)=>mode==='recent'?String(b.vvegui_modified_at).localeCompare(String(a.vvegui_modified_at)):String(a.Naam).localeCompare(String(b.Naam),'nl')*(mode==='za'?-1:1));$('list').innerHTML=sorted.map(p=>'<button class="item '+(current?.project?.ProjectID==p.ProjectID?'active':'')+'" onclick="openProject('+Number(p.ProjectID)+')"><strong>'+esc(p.Naam)+'</strong><span>'+({groen:'🟢',oranje:'🟠',rood:'🔴'}[p.Status]||'')+' '+esc(p.Status)+' · '+esc(p.vvegui_modified_at)+'</span></button>').join('')||'<div class="sidebar-search">Geen projecten gevonden.</div>'}
function audit(p){$('audit').hidden=false;$('audit').innerHTML='<span>Record-ID</span><span class="value">'+esc(p.ProjectID||'—')+'</span><span>Laatste wijziging</span><span class="value">'+esc(p.vvegui_modified_at||'—')+'</span><span>Door</span><span class="value">'+esc(p.vvegui_modified_by||'—')+'</span>'}
async function openProject(id){try{current=await req('get',{id});phase='Haalbaarheid';renderProject();renderList()}catch(e){err(e)}}
function newProject(){current={project:{ProjectID:0,Naam:'',Status:projectStatusOptions[0]?.id||'groen',StabuCode:'',MJOPReferentie:'',Haalbaarheid:'',Planning:'',Uitvoering:'',OpleveringNazorg:'',vvegui_modified_at:'—',vvegui_modified_by:'—'},assets:[],relations:[],documents:[],emails:[],photos:[],actions:[],checklist:[]};phase='Haalbaarheid';renderProject()}
function renderProject(){const p=current.project;$('title').textContent=p.Naam||'Nieuw project';$('subtitle').textContent='Project #'+(p.ProjectID||'nieuw');audit(p);const disabled=CAN_EDIT?'':'disabled';const phaseNames={Haalbaarheid:'Haalbaarheid',Planning:'Planning',Uitvoering:'Uitvoering',OpleveringNazorg:'Oplevering & nazorg'};$('detail').innerHTML='<div id="message" class="message"></div><div class="toolbar">'+(CAN_EDIT?'<button class="btn primary" onclick="saveProject()">💾 Wijzigingen opslaan</button>':'')+'<button class="btn" onclick="printReport()">📄 Rapport / PDF</button><button class="btn" onclick="exportCsv()">⬇ CSV</button></div><div class="grid"><div class="field"><label for="projectName">Projectnaam</label><input id="projectName" maxlength="255" value="'+esc(p.Naam)+'" '+disabled+'></div><div class="field"><label for="projectStatus">Voortgangsstatus</label><select id="projectStatus" '+disabled+'><option value="groen">🟢 Groen — op schema</option><option value="oranje">🟠 Oranje — aandacht nodig</option><option value="rood">🔴 Rood — geblokkeerd</option></select></div></div><div class="section"><div class="tabs">'+Object.entries(phaseNames).map(([key,label])=>'<button class="tab '+(phase===key?'active':'')+'" onclick="switchPhase(\''+key+'\')">'+label+'</button>').join('')+'</div><div class="phase-box"><label for="phaseText">'+phaseNames[phase]+'</label><textarea id="phaseText" '+disabled+'>'+esc(p[phase])+'</textarea></div></div><div class="section"><h3>🏢 Gekoppelde activa</h3><ul class="link-list">'+current.assets.map(a=>'<li><a href="./?module=Activa&id='+Number(a.ActivaID)+'">'+esc(a.Naam)+'</a>'+(CAN_EDIT?' <button class="btn" onclick="unlink(\'asset\','+Number(a.ActivaID)+')">✕</button>':'')+'</li>').join('')+'</ul>'+(CAN_EDIT?'<div class="picker"><select id="assetPick"><option value="">Selecteer activum…</option>'+assets.map(a=>'<option value="'+Number(a.ActivaID)+'">'+esc(a.Naam)+'</option>').join('')+'</select><button class="btn" onclick="link(\'asset\')">🔗 Koppelen</button></div>':'')+'</div><div class="section"><h3>📁 Gekoppelde bestanden</h3><ul class="link-list">'+current.documents.map(d=>'<li><a target="_blank" rel="noopener" href="document_download.php?id='+Number(d.DocumentID)+'&view=1">'+esc(d.Titel||d.OrigineleNaam)+'</a>'+(CAN_EDIT?' <button class="btn" onclick="unlink(\'document\','+Number(d.DocumentID)+')">✕</button>':'')+'</li>').join('')+'</ul>'+(CAN_EDIT?'<div class="picker"><input id="docQuery" placeholder="Zoek in bestandsbibliotheek" oninput="searchDocs()"><select id="docPick"><option value="">Zoek een bestand…</option></select><button class="btn" onclick="link(\'document\')">🔗 Koppelen</button></div>':'')+'</div><div class="section"><h3>📷 Foto’s</h3><div class="photo-grid">'+current.photos.map(f=>'<a target="_blank" rel="noopener" href="project_photo.php?id='+Number(f.FotoID)+'"><img loading="lazy" src="project_photo.php?id='+Number(f.FotoID)+'" alt="'+esc(f.Bestandsnaam)+'"></a>').join('')+'</div>'+(CAN_EDIT?'<div class="picker"><input id="photo" type="file" accept="image/jpeg,image/png,image/webp"><button class="btn" onclick="uploadPhoto()">⬆ Foto toevoegen</button></div>':'')+'</div><div class="section"><h3>✅ Actieregister</h3><table class="action-table"><thead><tr><th>Actie</th><th>Verantwoordelijk</th><th>Gereed op</th><th>Status</th></tr></thead><tbody>'+current.actions.map(a=>'<tr><td>'+esc(a.Actie)+'</td><td>'+esc(a.Verantwoordelijk)+'</td><td>'+esc(a.DatumCompleet)+'</td><td>'+(Number(a.Compleet)?'✓ Gereed':'Open')+'</td></tr>').join('')+'</tbody></table>'+(CAN_EDIT?'<div class="picker"><input id="actionText" placeholder="Nieuwe actie"><input id="actionWho" placeholder="Verantwoordelijke"><input id="actionDate" type="date"><label><input id="actionDone" type="checkbox"> Gereed</label><button class="btn" onclick="saveAction()">＋ Actie toevoegen</button></div>':'')+'</div>';$('projectStatus').value=p.Status||'groen'}
function syncInputs(){if(!current)return;current.project.Naam=$('projectName').value;current.project.Status=$('projectStatus').value;current.project[phase]=$('phaseText').value}function switchPhase(next){syncInputs();phase=next;renderProject()}
async function saveProject(){try{const actionDraft={text:$('actionText')?.value||'',who:$('actionWho')?.value||'',date:$('actionDate')?.value||'',done:$('actionDone')?.checked||false};syncInputs();current=await req('save',{id:current.project.ProjectID,body:current.project});renderProject();if(CAN_EDIT){$('actionText').value=actionDraft.text;$('actionWho').value=actionDraft.who;$('actionDate').value=actionDraft.date;$('actionDone').checked=actionDraft.done}await loadList();$('message').textContent='Project opgeslagen.'}catch(e){err(e)}}
async function link(kind){if(!current?.project?.ProjectID)return alert('Sla het project eerst op.');const linked=Number($(kind==='asset'?'assetPick':'docPick').value);if(!linked)return;try{current=await req('link_'+kind,{body:{linked_id:linked}});renderProject()}catch(e){err(e)}}
async function unlink(kind,id){if(!confirm('Koppeling verwijderen? Het gekoppelde record blijft bestaan.'))return;try{current=await req('unlink_'+kind,{body:{linked_id:id}});renderProject()}catch(e){err(e)}}
function fileType(x){const name=String(x.OrigineleNaam||'');const ext=name.includes('.')?name.split('.').pop().toLowerCase():'';const mime=String(x.Mimetype||'').toLowerCase();if(ext)return ext.toUpperCase();if(mime==='application/pdf')return 'PDF';if(mime.startsWith('image/'))return mime.slice(6).toUpperCase();return 'BESTAND'}
function fileDate(x){const date=String(x.Inhoudsdatum||'').slice(0,10);return /^\d{4}-\d{2}-\d{2}$/.test(date)?date:'inhoudsdatum onbekend'}
async function searchDocs(){try{const d=await req('documents',{query:'q='+encodeURIComponent($('docQuery').value)});docs=d.rows;$('docPick').innerHTML='<option value="">Selecteer bestand…</option>'+docs.map(x=>'<option value="'+Number(x.DocumentID)+'">'+esc(fileDate(x))+' · ['+esc(fileType(x))+'] '+esc(x.Titel||x.OrigineleNaam)+' · '+esc(x.OrigineleNaam||'')+'</option>').join('')}catch(e){err(e)}}
async function uploadPhoto(){if(!current?.project?.ProjectID)return alert('Sla het project eerst op.');const file=$('photo').files[0];if(!file)return;const form=new FormData();form.append('photo',file);try{current=await req('upload_photo',{method:'POST',body:form});renderProject()}catch(e){err(e)}}
async function saveAction(){if(!current?.project?.ProjectID)return alert('Sla het project eerst op.');try{current=await req('save_action',{body:{Actie:$('actionText').value,Verantwoordelijk:$('actionWho').value,DatumCompleet:$('actionDate').value,Compleet:$('actionDone').checked}});renderProject()}catch(e){err(e)}}
function printReport(){if(!current)return;syncInputs();window.print()}function exportCsv(){if(!current)return;syncInputs();const p=current.project;const keys=['ProjectID','Naam','Status','StabuCode','MJOPReferentie','Haalbaarheid','Planning','Uitvoering','OpleveringNazorg','vvegui_modified_at','vvegui_modified_by'];const csv='\ufeff'+keys.join(';')+'\r\n'+keys.map(k=>'"'+String(p[k]??'').replace(/"/g,'""')+'"').join(';');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));a.download='project-'+(p.ProjectID||'nieuw')+'.csv';a.click();URL.revokeObjectURL(a.href)}
function printReport(){if(!current)return;syncInputs();const p=current.project;const phases=[['Haalbaarheid','Haalbaarheid'],['Planning','Planning'],['Uitvoering','Uitvoering'],['OpleveringNazorg','Oplevering en nazorg']];const w=window.open('','_blank');if(!w)return alert('Sta pop-upvensters toe om het rapport te openen.');const html='<!doctype html><html lang="nl"><head><meta charset="utf-8"><title>Projectrapport '+esc(p.Naam)+'</title><style>body{font:14px system-ui,Arial,sans-serif;color:#17202a;margin:35px}h1{border-bottom:2px solid #2457a6;padding-bottom:10px}h2{background:#eaf4fb;padding:7px}p{white-space:pre-wrap;line-height:1.5}li{margin:5px 0}.meta{color:#667482}</style></head><body><h1>'+esc(p.Naam)+'</h1><p class="meta">Project #'+esc(p.ProjectID)+' · Status '+esc(p.Status)+' · Laatste wijziging '+esc(p.vvegui_modified_at)+' door '+esc(p.vvegui_modified_by)+'</p>'+phases.map(([key,label])=>'<h2>'+label+'</h2><p>'+esc(p[key]||'Geen tekst vastgelegd.')+'</p>').join('')+'<h2>Gekoppelde activa</h2><ul>'+current.assets.map(a=>'<li>'+esc(a.Naam)+'</li>').join('')+'</ul><h2>Gekoppelde bestanden</h2><ul>'+current.documents.map(d=>'<li>'+esc(d.Titel||d.OrigineleNaam)+'</li>').join('')+'</ul><h2>Actieregister</h2><ul>'+current.actions.map(a=>'<li>'+esc(a.Actie)+' — '+esc(a.Verantwoordelijk||'')+' — '+(Number(a.Compleet)?'gereed':'open')+'</li>').join('')+'</ul></body></html>';w.document.write(html);w.document.close();w.focus();w.print()}
const originalRenderProject=renderProject;
renderProject=function(){originalRenderProject();const label=document.querySelector('label[for="phaseText"]');if(label){$('phaseText').setAttribute('aria-label',label.textContent);label.remove()}renderChecklist();const fileSection=[...document.querySelectorAll('.section')].find(section=>section.querySelector('h3')?.textContent.includes('Gekoppelde bestanden'));fileSection?.querySelectorAll('.link-list li').forEach((li,index)=>{const doc=current.documents[index];if(!doc)return;li.querySelector('a')?.insertAdjacentHTML('afterend',' <small>· '+esc(fileDate(doc))+' · '+esc(fileType(doc))+'</small>');if(CAN_EDIT)li.insertAdjacentHTML('beforeend',' <label class="verified-date">Datum in document <input type="date" value="'+esc(doc.Inhoudsdatum||'')+'" aria-label="Inhoudsdatum van '+esc(doc.Titel||doc.OrigineleNaam)+'"><button class="btn" type="button" onclick="saveDocumentDate('+Number(doc.DocumentID)+',this)">💾 Datum</button></label>')})};
const renderProjectBeforeRelations=renderProject;
let relationOptions=[];
renderProject=function(){renderProjectBeforeRelations();const assetSection=[...document.querySelectorAll('.section')].find(section=>section.querySelector('h3')?.textContent.includes('Gekoppelde activa'));if(!assetSection)return;const linked=current.relations||[];const choices=relationOptions.filter(r=>!linked.some(existing=>Number(existing.RelatieID)===Number(r.RelatieID)));assetSection.insertAdjacentHTML('afterend','<div class="section" id="projectRelations"><h3>🔗 Uitvoerende firma’s / relaties</h3><ul class="link-list">'+linked.map(r=>'<li><a href="./?entity=relations&id='+Number(r.RelatieID)+'">'+esc(r.Naam||r.Alias||('Relatie '+r.RelatieID))+'</a>'+(CAN_EDIT?' <button class="btn" type="button" onclick="unlinkRelation('+Number(r.RelatieID)+')" aria-label="Relatie ontkoppelen">✕</button>':'')+'</li>').join('')+'</ul>'+(CAN_EDIT?'<div class="picker"><select id="relationPick"><option value="">Selecteer uitvoerende firma…</option>'+choices.map(r=>'<option value="'+Number(r.RelatieID)+'">'+esc(r.Naam||r.Alias||('Relatie '+r.RelatieID))+'</option>').join('')+'</select><button class="btn" type="button" onclick="linkRelation()">🔗 Koppelen</button></div>':'')+'</div>')};
async function changeRelation(action,relationId){if(!current?.project?.ProjectID)return alert('Sla het project eerst op.');const draft={name:$('projectName').value,status:$('projectStatus').value,text:$('phaseText').value};try{const updated=await req(action,{body:{linked_id:relationId}});current=updated;current.project.Naam=draft.name;current.project.Status=draft.status;current.project[phase]=draft.text;renderProject();$('message').textContent=action==='link_relation'?'Uitvoerende firma gekoppeld.':'Koppeling verwijderd; de relatie zelf blijft bestaan.'}catch(e){err(e)}}
function linkRelation(){const id=Number($('relationPick')?.value);if(id)changeRelation('link_relation',id)}
function unlinkRelation(id){changeRelation('unlink_relation',id)}
const renderProjectBeforeEmails=renderProject;
renderProject=function(){renderProjectBeforeEmails();const fileSection=[...document.querySelectorAll('.section')].find(section=>section.querySelector('h3')?.textContent.includes('Gekoppelde bestanden'));if(!fileSection)return;const linked=current.emails||[];fileSection.insertAdjacentHTML('beforeend','<div class="project-emails"><h4>✉ Gekoppelde e-mails</h4><ul class="link-list">'+linked.map(mail=>'<li><a target="_blank" rel="noopener" href="email_view.php?id='+Number(mail.EmailBerichtID)+'">'+esc(mail.Subject||'(geen onderwerp)')+'</a> <small>· '+esc(String(mail.SentAt||'').slice(0,16))+' · '+esc(mail.Sender||'')+'</small>'+(CAN_EDIT?' <button class="btn" type="button" onclick="unlinkProjectEmail('+Number(mail.EmailBerichtID)+')" aria-label="E-mail ontkoppelen">✕</button>':'')+'</li>').join('')+'</ul>'+(CAN_EDIT?'<div class="picker"><input id="emailQuery" aria-label="Zoek e-mail" placeholder="Zoek e-mail op onderwerp, afzender of inhoud" oninput="searchProjectEmails()"><select id="emailPick" aria-label="Selecteer e-mail"><option value="">Zoek een e-mail…</option></select><button class="btn" type="button" onclick="linkProjectEmail()">🔗 Koppelen</button></div>':'')+'</div>')};
let emailSearchTimer=0;
function searchProjectEmails(){clearTimeout(emailSearchTimer);emailSearchTimer=setTimeout(async()=>{const input=$('emailQuery'),picker=$('emailPick');if(!input||!picker)return;const query=input.value.trim();if(query.length<2){picker.innerHTML='<option value="">Typ minstens twee tekens…</option>';return}try{const result=await req('emails',{query:'q='+encodeURIComponent(query)});if(!picker.isConnected||input.value.trim()!==query)return;picker.innerHTML='<option value="">'+(result.rows.length?'Selecteer e-mail…':'Geen e-mails gevonden')+'</option>'+result.rows.map(mail=>'<option value="'+Number(mail.EmailBerichtID)+'">'+esc(String(mail.SentAt||'').slice(0,10))+' · '+esc(mail.Subject||'(geen onderwerp)')+' · '+esc(mail.Sender||'')+'</option>').join('')}catch(e){err(e)}},250)}
async function changeProjectEmail(action,emailId){if(!current?.project?.ProjectID)return alert('Sla het project eerst op.');const draft={name:$('projectName').value,status:$('projectStatus').value,text:$('phaseText').value};try{const updated=await req(action,{body:{linked_id:emailId}});current=updated;current.project.Naam=draft.name;current.project.Status=draft.status;current.project[phase]=draft.text;renderProject();$('message').textContent=action==='link_email'?'E-mail gekoppeld.':'E-mailkoppeling verwijderd; het bericht blijft bestaan.'}catch(e){err(e)}}
function linkProjectEmail(){const id=Number($('emailPick')?.value);if(id)changeProjectEmail('link_email',id)}
function unlinkProjectEmail(id){changeProjectEmail('unlink_email',id)}
const renderProjectBeforeActionEditor=renderProject;
renderProject=function(){renderProjectBeforeActionEditor();if(!CAN_EDIT)return;const tbody=document.querySelector('.action-table tbody');if(!tbody)return;tbody.innerHTML=(current.actions||[]).map(action=>'<tr data-action-id="'+Number(action.ActieID)+'"><td><input class="action-edit-text" aria-label="Actie" value="'+esc(action.Actie||'')+'"></td><td><input class="action-edit-who" aria-label="Verantwoordelijk" value="'+esc(action.Verantwoordelijk||'')+'"></td><td><input class="action-edit-date" aria-label="Gereed op" type="date" value="'+esc(String(action.DatumCompleet||'').slice(0,10))+'"></td><td><label><input class="action-edit-done" type="checkbox" '+(Number(action.Compleet)?'checked':'')+'> Gereed</label><button class="btn" type="button" onclick="saveProjectAction('+Number(action.ActieID)+')" aria-label="Actiepunt opslaan">💾</button> <button class="btn" type="button" onclick="deleteProjectAction('+Number(action.ActieID)+',this)" aria-label="Actiepunt verwijderen">✕</button></td></tr>').join('')};
async function saveProjectAction(actionId){const row=document.querySelector('[data-action-id="'+Number(actionId)+'"]');if(!row)return;const body={ActieID:actionId,Actie:row.querySelector('.action-edit-text').value.trim(),Verantwoordelijk:row.querySelector('.action-edit-who').value.trim(),DatumCompleet:row.querySelector('.action-edit-date').value,Compleet:row.querySelector('.action-edit-done').checked};if(!body.Actie)return alert('Vul een actie in.');try{const updated=await req('save_action',{body});current.actions=updated.actions;$('message').textContent='Actiepunt gewijzigd.'}catch(e){err(e)}}
async function deleteProjectAction(actionId,button){if(button.dataset.confirmDelete!=='yes'){button.dataset.confirmDelete='yes';button.textContent='Wissen?';button.setAttribute('aria-label','Klik nogmaals om het actiepunt definitief te verwijderen');$('message').textContent='Klik nogmaals op Wissen? om dit actiepunt definitief te verwijderen.';setTimeout(()=>{if(button.isConnected&&button.dataset.confirmDelete==='yes'){button.dataset.confirmDelete='';button.textContent='✕';button.setAttribute('aria-label','Actiepunt verwijderen')}},8000);return}button.disabled=true;try{const updated=await req('delete_action',{body:{ActieID:actionId}});current.actions=updated.actions;document.querySelector('[data-action-id="'+Number(actionId)+'"]')?.remove();$('message').textContent='Actiepunt verwijderd.'}catch(e){button.disabled=false;button.dataset.confirmDelete='';button.textContent='✕';$('message').textContent='Verwijderen mislukt: '+(e.message||String(e))}}
async function saveDocumentDate(documentId,button){if(!current?.project?.ProjectID)return;const input=button.closest('.verified-date')?.querySelector('input');if(!input)return;try{const updated=await req('save_document_date',{body:{DocumentID:documentId,Inhoudsdatum:input.value}});current.documents=updated.documents;const text=button.closest('li')?.querySelector('small');if(text){const doc=current.documents.find(d=>Number(d.DocumentID)===documentId);text.textContent='· '+fileDate(doc)+' · '+fileType(doc)}$('message').textContent='Gecontroleerde inhoudsdatum opgeslagen.'}catch(e){err(e)}}
unlink=async function(kind,id){if(!current?.project?.ProjectID)return;const draft={name:$('projectName').value,status:$('projectStatus').value,text:$('phaseText').value};try{const updated=await req('unlink_'+kind,{body:{linked_id:id}});const remaining=kind==='document'?updated.documents:updated.assets;if(remaining.some(row=>Number(row[kind==='document'?'DocumentID':'ActivaID'])===Number(id)))throw Error('Ontkoppelen is niet gelukt.');current=updated;current.project.Naam=draft.name;current.project.Status=draft.status;current.project[phase]=draft.text;renderProject();$('message').textContent='Koppeling verwijderd; het bestand of activum zelf blijft bestaan.'}catch(e){err(e)}};
function renderChecklist(){const box=document.querySelector('.phase-box');if(!box)return;const items=(current.checklist||[]).filter(item=>item.Fase===phase);const disabled=CAN_EDIT?'':'disabled';box.insertAdjacentHTML('beforeend','<div class="checklist-wrap"><h3>☑ Checklist — '+esc(phase==='OpleveringNazorg'?'Oplevering & nazorg':phase)+'</h3><table class="checklist-table"><thead><tr><th>Gereed</th><th>Criterium</th><th>Datum</th><th>Acties</th></tr></thead><tbody>'+items.map(item=>'<tr data-check-id="'+Number(item.ChecklistID)+'"><td><input class="check-done-input" type="checkbox" '+(Number(item.Compleet)?'checked ':'')+disabled+' aria-label="Gereed"></td><td><input class="check-criterion '+(Number(item.Compleet)?'check-done':'')+'" type="text" maxlength="500" value="'+esc(item.Criterium)+'" '+disabled+' aria-label="Criterium"></td><td><input class="check-date" type="date" value="'+esc(item.Datum||'')+'" '+disabled+' aria-label="Datum"></td><td>'+(CAN_EDIT?'<div class="checklist-actions"><button class="btn" type="button" onclick="saveChecklist('+Number(item.ChecklistID)+')" aria-label="Regel opslaan">💾</button><button class="btn" type="button" onclick="deleteChecklist('+Number(item.ChecklistID)+')" aria-label="Regel verwijderen">✕</button></div>':'')+'</td></tr>').join('')+(CAN_EDIT?'<tr id="newChecklistRow"><td><input class="check-done-input" type="checkbox" aria-label="Nieuwe regel gereed"></td><td><input class="check-criterion" type="text" maxlength="500" placeholder="Nieuw criterium" aria-label="Nieuw criterium"></td><td><input class="check-date" type="date" aria-label="Datum nieuwe regel"></td><td><button class="btn" type="button" onclick="saveChecklist(0)">＋ Toevoegen</button></td></tr>':'')+'</tbody></table><p class="checklist-hint">Wijzigingen per regel opslaan met 💾. De datum is de geplande of feitelijke datum van het criterium.</p></div>')}
async function saveChecklist(checkId){if(!current?.project?.ProjectID)return alert('Sla het project eerst op.');const row=checkId?document.querySelector('[data-check-id="'+checkId+'"]'):$('newChecklistRow');if(!row)return;const body={ChecklistID:checkId,Fase:phase,Criterium:row.querySelector('.check-criterion').value,Datum:row.querySelector('.check-date').value,Compleet:row.querySelector('.check-done-input').checked};try{const saved=await req('save_checklist',{body});current.checklist=saved.checklist;renderChecklistReplace()}catch(e){err(e)}}
async function deleteChecklist(checkId){if(!confirm('Checklistregel verwijderen?'))return;try{const saved=await req('delete_checklist',{body:{ChecklistID:checkId}});current.checklist=saved.checklist;renderChecklistReplace()}catch(e){err(e)}}
function renderChecklistReplace(){document.querySelector('.checklist-wrap')?.remove();renderChecklist()}
function projectReportWithChecklist(){if(!current)return;syncInputs();const p=current.project;const phases=[['Haalbaarheid','Haalbaarheid'],['Planning','Planning'],['Uitvoering','Uitvoering'],['OpleveringNazorg','Oplevering en nazorg']];const w=window.open('','_blank');if(!w)return alert('Sta pop-upvensters toe om het rapport te openen.');const phaseHtml=phases.map(([key,label])=>{const items=(current.checklist||[]).filter(item=>item.Fase===key);return '<h2>'+label+'</h2><p>'+esc(p[key]||'Geen tekst vastgelegd.')+'</p>'+(items.length?'<table><thead><tr><th>Gereed</th><th>Criterium</th><th>Datum</th></tr></thead><tbody>'+items.map(item=>'<tr><td>'+(Number(item.Compleet)?'☑':'☐')+'</td><td>'+esc(item.Criterium)+'</td><td>'+esc(item.Datum||'')+'</td></tr>').join('')+'</tbody></table>':'')}).join('');const html='<!doctype html><html lang="nl"><head><meta charset="utf-8"><title>Projectrapport '+esc(p.Naam)+'</title><style>body{font:14px system-ui,Arial,sans-serif;color:#17202a;margin:35px}h1{border-bottom:2px solid #2457a6;padding-bottom:10px}h2{background:#eaf4fb;padding:7px}p{white-space:pre-wrap;line-height:1.5}li{margin:5px 0}.meta{color:#667482}table{width:100%;border-collapse:collapse;margin:10px 0 20px}th,td{padding:6px;border-bottom:1px solid #d7e0e8;text-align:left}th{background:#eaf4fb}</style></head><body><h1>'+esc(p.Naam)+'</h1><p class="meta">Project #'+esc(p.ProjectID)+' · Status '+esc(p.Status)+' · Laatste wijziging '+esc(p.vvegui_modified_at)+' door '+esc(p.vvegui_modified_by)+'</p>'+phaseHtml+'<h2>Gekoppelde activa</h2><ul>'+current.assets.map(a=>'<li>'+esc(a.Naam)+'</li>').join('')+'</ul><h2>Gekoppelde bestanden</h2><ul>'+current.documents.map(d=>'<li>'+esc(d.Titel||d.OrigineleNaam)+'</li>').join('')+'</ul><h2>Gekoppelde e-mails</h2><ul>'+(current.emails||[]).map(mail=>'<li>'+esc(mail.Subject||'(geen onderwerp)')+' — '+esc(String(mail.SentAt||'').slice(0,16))+'</li>').join('')+'</ul><h2>Actieregister</h2><ul>'+current.actions.map(a=>'<li>'+esc(a.Actie)+' — '+esc(a.Verantwoordelijk||'')+' — '+(Number(a.Compleet)?'gereed':'open')+'</li>').join('')+'</ul></body></html>';w.document.write(html);w.document.close();w.focus();w.print()}
printReport=function(){if(!current?.project?.ProjectID)return alert('Sla het project eerst op.');window.location.href='project_export_pdf.php?id='+Number(current.project.ProjectID)};
const renderProjectBeforeCodes=renderProject;
renderProject=function(){renderProjectBeforeCodes();const grid=document.querySelector('#detail>.grid');if(!grid)return;const p=current.project,disabled=CAN_EDIT?'':'disabled';const projectSelect=$('projectStatus');if(projectSelect){const choices=[...projectStatusOptions];if(p.Status&&!choices.some(x=>String(x.id)===String(p.Status)))choices.unshift({id:p.Status,label:String(p.Status)+' — bestaande status'});projectSelect.innerHTML=choices.map(x=>'<option value="'+esc(x.id)+'">'+esc(x.label)+'</option>').join('');projectSelect.value=p.Status||choices[0]?.id||''}const stabu=[...stabuOptions];if(p.StabuCode&&!stabu.some(x=>String(x.id)===String(p.StabuCode)))stabu.unshift({id:p.StabuCode,label:p.StabuCode+' — bestaande verwijzing'});const mjop=[...mjopOptions];if(p.MJOPReferentie&&!mjop.some(x=>String(x.id)===String(p.MJOPReferentie)))mjop.unshift({id:p.MJOPReferentie,label:p.MJOPReferentie+' — bestaande verwijzing'});const options=(items,value,empty)=>'<option value="">'+empty+'</option>'+items.map(x=>'<option value="'+esc(x.id)+'" '+(String(x.id)===String(value||'')?'selected':'')+'>'+esc(x.label)+'</option>').join('');grid.insertAdjacentHTML('afterend','<div class="project-code-grid"><div class="field"><label for="projectStabu">STABU-code</label><select id="projectStabu" '+disabled+'>'+options(stabu,p.StabuCode,'— Geen keuze —')+'</select></div><div class="field"><label for="projectMjop">MJOP-referentie</label><select id="projectMjop" '+disabled+' onchange="updateProjectMjopLink()">'+options(mjop,p.MJOPReferentie,'— Geen keuze —')+'</select><div id="projectMjopLink" class="project-mjop-link"></div></div></div>');updateProjectMjopLink()};
function updateProjectMjopLink(){const value=$('projectMjop')?.value||'';const option=mjopOptions.find(x=>String(x.id)===String(value));const box=$('projectMjopLink');if(!box)return;box.innerHTML=option?.url?'<a target="_blank" rel="noopener" href="'+esc(option.url)+'">Open hoofdgroep in het MJOP op pagina '+esc(option.page)+'</a>':''}
const syncInputsBeforeCodes=syncInputs;
syncInputs=function(){syncInputsBeforeCodes();if(!current)return;current.project.StabuCode=$('projectStabu')?.value||'';current.project.MJOPReferentie=$('projectMjop')?.value||''};
async function init(){try{const [a,r,o]=await Promise.all([req('assets'),req('relations'),req('project_options')]);assets=a.rows;relationOptions=r.rows;stabuOptions=o.stabu||[];mjopOptions=o.mjop||[];projectStatusOptions=o.status||[];renderProjectStatusFilters()}catch(e){err(e)}await loadList();const id=Number(new URLSearchParams(location.search).get('id'));if(id)openProject(id)}init();
</script></body></html>
